    isPositiveNumber(240) === true &&
    isPositiveNumber(-5) === false &&
    isPositiveNumber(0) === false &&
    isPositiveNumber('abc') === false;
  console.log("All tests passed!" === allPassed ? "SUCCESS" : "FAILURE");
  process.exit(allPassed ? 0 : 1);
}

